<script lang="ts">import Icon, {type IconName} from './Icon.svelte';let {active,navigate}:{active:string,navigate:(route:string)=>void}=$props();const tabs:{route:string,label:string,icon:IconName}[]=[{route:'today',label:'Today',icon:'gauge'},{route:'sleep',label:'Sleep',icon:'moon'},{route:'training',label:'Training',icon:'bolt'},{route:'health',label:'Health',icon:'heart'}];</script><nav class="tabs" aria-label="Main navigation">{#each tabs as tab}<button class="tab" class:on={active===tab.route} onclick={()=>navigate(tab.route)}><span class="tab-icon"><Icon name={tab.icon} size={24}/></span>{tab.label}</button>{/each}</nav>
